@Injectable({ providedIn: 'root' })
export class CustomerStore {
  private readonly customerService = inject(CustomerService);

  // privat und schreibbar: nur der Store darf ändern
  private readonly _customers = signal<Customer[]>([]);
  private readonly _filter = signal('');
  private readonly _selectedId = signal<string | undefined>(undefined);
  private readonly _loading = signal(false);
  private readonly _error = signal<string | undefined>(undefined);

  // öffentlich und nur lesbar
  readonly customers = this._customers.asReadonly();
  readonly filter = this._filter.asReadonly();
  readonly selectedId = this._selectedId.asReadonly();
  readonly loading = this._loading.asReadonly();
  readonly error = this._error.asReadonly();

  readonly filtered = computed(() => {
    const f = this._filter().toLowerCase();
    return this._customers().filter(c => c.firstname?.toLowerCase().includes(f));
  });
  readonly selected = computed(() =>
    this._customers().find(c => c.id === this._selectedId()));
  readonly total = computed(() => this.filtered().length);

  async load(): Promise<void> {
    this._loading.set(true);
    this._error.set(undefined);
    try { this._customers.set(await firstValueFrom(this.customerService.getAll())); }
    catch { this._error.set('Fehler beim Laden der Kunden.'); }
    finally { this._loading.set(false); }
  }
  setFilter(text: string): void { this._filter.set(text); }
  select(id: string | undefined): void { this._selectedId.set(id); }
}

