@Injectable({ providedIn: 'root' })
export class CustomerStore {
  private readonly api = inject(CustomerService);
  private readonly _selectedId = signal<string | undefined>(undefined);
  // Liste: Observable direkt verwenden
  private readonly listRes = rxResource({ stream: () => this.api.getAll() });
  readonly customers = computed(() =>
    this.listRes.hasValue() ? this.listRes.value() : []);
  readonly loading = this.listRes.isLoading;
  readonly error = this.listRes.error;

  // Details: lädt neu, sobald sich selectedId ändert
  readonly detailsRes = resource({
    params: () => this._selectedId(),
    loader: ({ params: id }) => firstValueFrom(this.api.getById(id)),
  });
  reload() { this.listRes.reload(); }
}

type LoadState<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'loaded'; data: T };

private readonly _state = signal<LoadState<Customer[]>>({ status: 'idle' });
readonly state = this._state.asReadonly();

async load() {
  this._state.set({ status: 'loading' });
  try {
    const data = await firstValueFrom(this.api.getAll());
    this._state.set({ status: 'loaded', data });
  } catch {
    this._state.set({ status: 'error', message: 'Laden fehlgeschlagen' });
  }
}

