interface CustomerState {
  entities: Record<string, Customer>;   // id -> Kunde, jeder genau einmal
  ids: string[];                        // Reihenfolge der Liste
  favoriteIds: string[];
}
private readonly _state =
  signal<CustomerState>({ entities: {}, ids: [], favoriteIds: [] });
readonly all = computed(() => {
  const s = this._state();
  return s.ids.map(id => s.entities[id]);
});
readonly favorites = computed(() =>
  this._state().favoriteIds.map(id => this._state().entities[id]));

rename(id: string, firstname: string) {   // nur eine Stelle ändern
  this._state.update(s => ({ ...s,
    entities: { ...s.entities, [id]: { ...s.entities[id], firstname } } }));
}

